const slots=[{"name":"assets/imagen-01.png","label":"Marnez Desarrollos"},{"name":"assets/imagen-02.jpg","label":"Comunidad Marnez"},{"name":"assets/arleen.png","label":"Arleen, asesora Marnez"},{"name":"assets/imagen-03.jpg","label":"Asesores Marnez trabajando en equipo"},{"name":"assets/imagen-04.jpg","label":"Sesión de trabajo del equipo Marnez"},{"name":"assets/imagen-05.jpg","label":"Equipo comercial Marnez"},{"name":"assets/ruta-capacitacion.jpg","label":"Capacitación comercial en equipo"},{"name":"assets/ruta-coaching.jpg","label":"Coaching individual acompañado"},{"name":"assets/ruta-practica.jpg","label":"Imagen ilustrativa: presentación de un proyecto a clientes"},{"name":"assets/ruta-prospeccion.jpg","label":"Imagen ilustrativa: prospección telefónica y digital"},{"name":"assets/ruta-primera-venta.jpg","label":"Imagen ilustrativa: celebración de una primera venta"},{"name":"assets/ingreso-resultados.jpg","label":"Imagen ilustrativa: asesora celebrando sus resultados comerciales"},{"name":"assets/elige-turno.jpg","label":"Asesora organizando su agenda y eligiendo su turno"},{"name":"assets/coaching-equipo.jpg","label":"Acompañamiento comercial"},{"name":"assets/imagen-07.jpg","label":"Oficinas Marnez"},{"name":"assets/imagen-08.jpg","label":"Acceso de Arennea"},{"name":"assets/imagen-09.png","label":"Arennea"},{"name":"assets/imagen-10.jpg","label":"Andadores y áreas verdes"},{"name":"assets/imagen-11.jpg","label":"Asadores"},{"name":"assets/imagen-12.jpg","label":"Cancha de usos múltiples"},{"name":"assets/imagen-13.jpg","label":"Pet Park"},{"name":"assets/imagen-14.jpg","label":"Comunidad Marnez"},{"name":"assets/imagen-06.jpg","label":"Entrega a clientes"},{"name":"assets/imagen-15.jpg","label":"Inauguración Marnez"}];
const adminHTML="<!doctype html><html lang=\"es\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>Administración · Arennea</title>\n<style>\n:root{font-family:Inter,system-ui,sans-serif;color:#eaf2ed;background:#091c24}*{box-sizing:border-box}body{margin:0}header{padding:24px max(24px,calc((100vw - 1200px)/2));background:#102b34;display:flex;justify-content:space-between;align-items:center;gap:18px;border-bottom:1px solid #ffffff16}header strong{font-size:20px}small{display:block;color:#acbdb9;margin-top:7px}main{max-width:1200px;margin:42px auto;padding:0 24px}h1{font-size:clamp(28px,4vw,42px);margin:0 0 12px}p{color:#afc1bd;line-height:1.6}button,.link{border:1px solid #ffffff25;border-radius:9px;padding:12px 17px;font:600 14px system-ui;cursor:pointer;background:#204738;color:white;text-decoration:none;display:inline-block}button:hover,.link:hover{background:#2c5c49}button:disabled{opacity:.45;cursor:wait}.secondary{background:transparent}.actions{display:flex;gap:10px;flex-wrap:wrap}input[type=password]{width:100%;padding:15px;border:1px solid #6c8582;border-radius:8px;background:#091c24;color:white;font-size:17px;margin:12px 0 20px}label{display:block;font-size:14px}.login{max-width:420px;margin:12vh auto;padding:30px;background:#102b34;border:1px solid #ffffff20;border-radius:18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:30px}.card{background:#102b34;border:1px solid #ffffff20;border-radius:14px;overflow:hidden}.card img{width:100%;height:210px;object-fit:contain;background:repeating-conic-gradient(#415555 0 25%,#354a4a 0 50%) 0/20px 20px}.card-body{padding:20px}.card h2{font-size:17px;line-height:1.4;margin:0 0 8px}.card p{font-size:13px;margin:8px 0 16px}.card button{padding:10px 12px;font-size:13px}.status{min-height:24px;color:#efd18d!important}.notice{background:#173a37;border-radius:10px;padding:16px 20px}input[type=file]{width:100%;font-size:13px;margin:4px 0 14px;color:#c7d9d1}input::file-selector-button{padding:9px;border:0;border-radius:6px;margin-right:10px;cursor:pointer}[hidden]{display:none!important}:focus-visible{outline:3px solid #e2b769;outline-offset:4px}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid{grid-template-columns:1fr}header{flex-direction:column;align-items:flex-start}}\n.stats-box{padding:26px;background:#102b34;border:1px solid #ffffff20;border-radius:16px;margin-bottom:40px}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.filters input{display:block;padding:10px;background:#091c24;color:#fff;border:1px solid #6c8582;border-radius:8px;margin-top:7px;font:inherit;color-scheme:dark}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:22px 0}.metric{padding:22px;background:#091c24;border-radius:12px}.metric strong{display:block;font-size:42px;color:#efd18d;margin-top:8px}.stats-box table{width:100%;border-collapse:collapse;margin-top:14px;font-size:14px}.stats-box td,.stats-box th{padding:10px;border-bottom:1px solid #ffffff15;text-align:right}.stats-box td:first-child,.stats-box th:first-child{text-align:left}.stats-box .table-scroll{max-height:320px;overflow:auto}.stats-box h2{margin-top:0}.presets{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.stats-note{font-size:13px}@media(max-width:600px){.stats-box{padding:18px}.metric{padding:14px}.metric strong{font-size:32px}.filters label,.filters input{width:100%}}\n\n.admin-tabs{display:flex;gap:10px;margin:0 0 26px}.admin-tabs [aria-pressed=true]{background:#efd18d;color:#102b34}.text-tools{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:24px 0}.text-tools input,.text-tools select,.copy-field textarea{display:block;width:100%;border:1px solid #54716d;background:#091c24;color:#fff;border-radius:8px;padding:12px;font:15px system-ui;margin-top:8px}.copy-group{border:1px solid #ffffff20;border-radius:12px;margin:18px 0;overflow:hidden}.copy-group summary{padding:20px;background:#173a37;cursor:pointer;font-weight:700}.copy-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:22px}.copy-field{padding:14px;background:#0b222b;border-radius:10px}.copy-field textarea{min-height:90px;resize:vertical;line-height:1.6}.copy-field button{font-size:12px;padding:7px 10px;margin-top:10px}.copy-field label{line-height:1.5;color:#d3dfd9}.copy-field.dirty{outline:1px solid #efd18d}.text-save{position:sticky;bottom:0;background:#102b34f5;padding:18px 0;border-top:1px solid #ffffff25;display:flex;align-items:center;gap:12px;flex-wrap:wrap}.text-save span{font-size:14px;color:#efd18d}@media(max-width:650px){.text-tools,.copy-grid{grid-template-columns:1fr}.copy-grid{padding:12px}.admin-tabs{flex-wrap:wrap}}\n\n.engagement-panel{border-top:1px solid #ffffff25;padding-top:30px;margin-top:30px}.engagement-panel .metric strong{font-size:34px}.engagement-panel th{white-space:normal}.table-scroll{overflow:auto}.stats-box th:first-child,.stats-box td:first-child{min-width:130px}\n#text-fields{display:grid;gap:18px}#text-fields fieldset{min-width:0;padding:16px;border:1px solid #54716d;border-radius:12px}#text-fields select{max-width:100%;width:100%;padding:10px}#text-fields textarea{box-sizing:border-box}</style>\n<header><div><strong>ARENNEA <span style=\"font-weight:400;color:#b8c9be\">/ Administración</span></strong><small>Administración privada · Marnez</small></div><div class=\"actions\"><a class=\"link secondary\" href=\"/\" target=\"_blank\" rel=\"noopener\">Ver landing ↗</a><button id=\"logout\" class=\"secondary\" hidden>Cerrar sesión</button></div></header>\n<main>\n<form id=\"login\" class=\"login\"><h1>Bienvenido</h1><p>Ingresa para actualizar los textos e imágenes de tu landing.</p><label for=\"password\">Contraseña</label><input id=\"password\" type=\"password\" required autocomplete=\"current-password\"><button>Entrar al administrador</button><p id=\"login-status\" class=\"status\" role=\"status\"></p></form>\n<section id=\"panel\" hidden>\n<nav class=\"admin-tabs\" aria-label=\"Administración\"><button type=\"button\" data-tab=\"texts\" aria-pressed=\"true\">Textos</button><button type=\"button\" data-tab=\"images\" aria-pressed=\"false\">Imágenes</button><button type=\"button\" data-tab=\"stats\" aria-pressed=\"false\">Visitas</button></nav>\n<section id=\"texts-panel\" class=\"stats-box\"><h1>Todos los textos de tu landing</h1><p>Edita por sección y presiona <strong>Guardar textos y enlaces</strong>. Los títulos divididos en líneas se editan por partes para conservar el diseño. Los textos repetidos del menú y los botones tienen su propio campo. Los cambios no se publican hasta que los guardes.</p>\n<div class=\"text-tools\"><label>Sección<select id=\"text-section\"><option value=\"\">Todas las secciones</option></select></label><label>Buscar texto<input id=\"text-search\" type=\"search\" placeholder=\"Ej. entrevista, precio, comisión\"></label></div>\n<div id=\"text-fields\"></div><div class=\"text-save\"><button id=\"save-texts\" type=\"button\" disabled>Guardar textos y enlaces</button><button id=\"reload-texts\" type=\"button\" class=\"secondary\">Descartar cambios</button><span id=\"text-status\" role=\"status\" aria-live=\"polite\">Cargando textos…</span></div></section>\n\n<section id=\"stats-panel\" hidden class=\"stats-box\" aria-labelledby=\"stats-title\"><h2 id=\"stats-title\">Visitas a tu landing</h2><p>Consulta cuántos visitantes llegan y cuántas veces abren la página.</p>\n<div class=\"presets\"><button type=\"button\" data-days=\"1\" class=\"secondary\">Hoy</button><button type=\"button\" data-days=\"7\" class=\"secondary\">Últimos 7 días</button><button type=\"button\" data-days=\"30\" class=\"secondary\">Últimos 30 días</button><button type=\"button\" data-days=\"all\" class=\"secondary\">Todo el periodo</button></div>\n<form id=\"stats-filter\" class=\"filters\"><label>Desde<input type=\"date\" id=\"stats-start\" required></label><label>Hasta<input type=\"date\" id=\"stats-end\" required></label><button id=\"stats-submit\">Consultar</button></form>\n<p id=\"stats-status\" class=\"status\" role=\"status\"></p>\n<div class=\"metrics\"><div class=\"metric\">Visitantes únicos estimados<strong id=\"stat-visitors\">—</strong></div><div class=\"metric\">Visitas totales<strong id=\"stat-views\">—</strong></div></div>\n<p id=\"stats-period\" class=\"stats-note\"></p><p class=\"stats-note\">Un visitante se estima por navegador mediante una cookie anónima. Cada apertura o recarga cuenta como visita. Cambiar de dispositivo o borrar cookies puede duplicar visitantes. No contamos tus visitas mientras tengas sesión de administrador ni robots conocidos. Horario de Mérida; ambas fechas incluidas.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Fecha</th><th>Visitantes</th><th>Visitas</th></tr></thead><tbody id=\"stats-days\"></tbody></table></div><p class=\"stats-note\">Los visitantes únicos del periodo no son la suma de los visitantes de cada día.</p>\n<div class=\"engagement-panel\"><h2>Clics y recorrido</h2><p id=\"engagement-start\" class=\"stats-note\"></p>\n<div class=\"metrics\"><div class=\"metric\">Recorridos registrados<strong id=\"stat-journeys\">—</strong></div><div class=\"metric\">Clics a Calendly<strong id=\"stat-clicks\">—</strong></div><div class=\"metric\">Recorridos con clic<strong id=\"stat-ctr\">—</strong></div><div class=\"metric\">Profundidad máxima promedio<strong id=\"stat-depth\">—</strong></div></div>\n<h3>¿Qué botón seleccionan?</h3><div class=\"table-scroll\"><table><thead><tr><th>Botón</th><th>Clics</th><th>Recorridos con clic</th><th>Visitantes</th></tr></thead><tbody id=\"engagement-buttons\"></tbody></table></div><p class=\"stats-note\">Los clics cuentan intentos de abrir Calendly, no entrevistas agendadas. Un visitante puede seleccionar varios botones.</p>\n<h3>¿Hasta dónde llegan?</h3><div class=\"table-scroll\"><table><thead><tr><th>Sección</th><th>Recorridos que la vieron</th><th>Alcance</th><th>Última sección registrada</th></tr></thead><tbody id=\"engagement-sections\"></tbody></table></div>\n<p class=\"stats-note\">Un recorrido es una apertura de la landing con seguimiento activo. “Última sección registrada” indica dónde quedó la visita al cerrar, cambiar de pestaña o dejar de interactuar; también puede incluir visitas aún abiertas. Es una aproximación al punto de salida, no una salida confirmada. No todas las visitas permiten medición: bloqueadores o restricciones del navegador pueden impedirla.</p><p class=\"stats-note\">El alcance se calcula sobre los recorridos registrados del periodo. La profundidad mide la posición más baja de pantalla alcanzada, no garantiza lectura. Las visitas históricas no tienen datos de recorrido. Tus visitas con sesión de administrador están excluidas.</p>\n</div></section>\n<section id=\"images-panel\" hidden><h1>Tu landing, con tus imágenes.</h1><p>Elige una imagen, revisa la vista previa y presiona <strong>Publicar imagen</strong>. Puedes restaurar la imagen original en cualquier momento.</p><p class=\"notice\">JPG, PNG o WebP · Hasta 15 MB por archivo. Las imágenes se optimizan antes de guardarse. Los logotipos conservan la transparencia.</p><p id=\"global-status\" role=\"status\"></p><div id=\"grid\" class=\"grid\"></div></section></section>\n</main>\n<script>\nconst $=s=>document.querySelector(s);\nasync function api(url,options={}){const r=await fetch(url,{...options,headers:{'X-Requested-With':'ArenneaAdmin',...options.headers}});let d;try{d=await r.json()}catch{d={error:'No se pudo completar la solicitud.'}}if(!r.ok){if(r.status===401){$('#panel').hidden=true;$('#login').hidden=false;$('#logout').hidden=true;}throw new Error(d.error||'No se pudo guardar.')}return d}\nasync function load(){const data=await api('/api/admin/images');$('#login').hidden=true;$('#panel').hidden=false;$('#logout').hidden=false;loadStats().catch(()=>{});loadTexts().catch(e=>{$('#text-status').textContent=e.message});$('#grid').replaceChildren();for(const item of data.images){const card=document.createElement('article');card.className='card';card.innerHTML='<img><div class=\"card-body\"><h2></h2><p class=\"saved\"></p><label>Elegir nueva imagen<input type=\"file\" accept=\"image/jpeg,image/png,image/webp\"></label><div class=\"actions\"><button class=\"save\" disabled>Publicar imagen</button><button class=\"reset secondary\">Restaurar original</button></div><p class=\"status\" role=\"status\"></p></div>';const img=card.querySelector('img'),input=card.querySelector('input'),save=card.querySelector('.save'),reset=card.querySelector('.reset'),status=card.querySelector('.status');img.src='/'+item.name+'?v='+Date.now();img.alt=item.label;card.querySelector('h2').textContent=item.label;card.querySelector('.saved').textContent=item.updated?'Personalizada · '+new Date(item.updated).toLocaleString('es-MX'):'Imagen original';let blob=null,preview=null;\ninput.onchange=async()=>{blob=null;save.disabled=true;status.textContent='Preparando vista previa…';try{const file=input.files[0];if(!file){status.textContent='';return}if(file.size>15*1024*1024)throw Error('El archivo supera 15 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Selecciona JPG, PNG o WebP.');const bitmap=await createImageBitmap(file);let max=1600;for(let attempt=0;attempt<4;attempt++){const ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84-attempt*.08));if(blob&&blob.size<=1024*1024)break;max=Math.round(max*.8)}bitmap.close();if(!blob||blob.size>1024*1024)throw Error('No se pudo optimizar esta imagen. Prueba otra más pequeña.');if(preview)URL.revokeObjectURL(preview);preview=URL.createObjectURL(blob);img.src=preview;save.disabled=false;status.textContent='Vista previa lista. Aún no está publicada.';}catch(e){status.textContent=e.message}};\nsave.onclick=async()=>{save.disabled=true;reset.disabled=true;input.disabled=true;status.textContent='Guardando…';try{await api('/api/admin/images/'+encodeURIComponent(item.name),{method:'PUT',headers:{'Content-Type':blob.type},body:blob});img.src='/'+item.name+'?v='+Date.now();status.textContent='Imagen publicada. Ya se muestra en la landing.';card.querySelector('.saved').textContent='Personalizada · guardada ahora';blob=null;input.value='';if(preview){URL.revokeObjectURL(preview);preview=null}}catch(e){status.textContent=e.message;save.disabled=false}finally{reset.disabled=false;input.disabled=false}};\nreset.onclick=async()=>{if(!confirm('¿Restaurar la imagen original de esta sección?'))return;save.disabled=true;reset.disabled=true;input.disabled=true;try{await api('/api/admin/images/'+encodeURIComponent(item.name),{method:'DELETE'});img.src='/'+item.name+'?v='+Date.now();input.value='';blob=null;if(preview){URL.revokeObjectURL(preview);preview=null}card.querySelector('.saved').textContent='Imagen original';status.textContent='Imagen original restaurada.'}catch(e){status.textContent=e.message;save.disabled=!blob}finally{reset.disabled=false;input.disabled=false}};\n$('#grid').append(card)}}\n$('#login').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#login-status').textContent='Ingresando…';try{await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#password').value})});$('#password').value='';$('#login-status').textContent='';await load()}catch(e){$('#login-status').textContent=e.message}finally{b.disabled=false}};\n$('#logout').onclick=async()=>{try{await api('/api/admin/logout',{method:'POST'});location.reload()}catch(e){$('#global-status').textContent=e.message}};\n\nlet statsStarted=null,statsRequest=0;\nconst dayAt=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Merida',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);\nfunction selectPeriod(days){const today=dayAt(new Date());$('#stats-end').value=today;$('#stats-start').value=days==='all'?(statsStarted?dayAt(new Date(statsStarted)):today):new Date(Date.parse(today+'T12:00:00Z')-(Number(days)-1)*86400000).toISOString().slice(0,10)}\nselectPeriod(7);\nasync function loadStats(){\n const version=++statsRequest;$('#stats-submit').disabled=true;$('#stats-status').textContent='Consultando…';\n try{const data=await api('/api/admin/stats?'+new URLSearchParams({start:$('#stats-start').value,end:$('#stats-end').value}));if(version!==statsRequest)return;\n statsStarted=data.startedAt;$('#stat-visitors').textContent=Number(data.totals.visitors).toLocaleString('es-MX');$('#stat-views').textContent=Number(data.totals.views).toLocaleString('es-MX');\n $('#stats-period').textContent='Periodo: '+data.start+' al '+data.end+'. Conteo disponible desde '+(statsStarted?dayAt(new Date(statsStarted)):'esta actualización')+'. No hay datos anteriores.';\n $('#stats-days').replaceChildren();if(!data.days.length){const row=document.createElement('tr');const cell=document.createElement('td');cell.colSpan=3;cell.textContent='Sin visitas registradas en este periodo.';row.append(cell);$('#stats-days').append(row)}\n for(const day of data.days){const row=document.createElement('tr');for(const value of [day.day,day.visitors,day.views]){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}$('#stats-days').append(row)}\n renderEngagement(data.engagement);$('#stats-status').textContent='Datos actualizados.';\n }catch(e){if(version===statsRequest){$('#stat-visitors').textContent='—';$('#stat-views').textContent='—';$('#stats-days').replaceChildren();$('#stats-period').textContent='';$('#stats-status').textContent=e.message;renderEngagement(null)}}finally{if(version===statsRequest)$('#stats-submit').disabled=false}\n}\n$('#stats-filter').onsubmit=e=>{e.preventDefault();loadStats()};\ndocument.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{selectPeriod(b.dataset.days);loadStats()});\n\n\nfunction renderEngagement(data){\n for(const id of ['stat-journeys','stat-clicks','stat-ctr','stat-depth'])$('#'+id).textContent='—';for(const id of ['engagement-buttons','engagement-sections'])$('#'+id).replaceChildren();$('#engagement-start').textContent='';if(!data)return;\n const n=Number(data.totals.journeys)||0,clicks=data.buttons.reduce((sum,b)=>sum+Number(b.clicks||0),0);$('#stat-journeys').textContent=n.toLocaleString('es-MX');$('#stat-clicks').textContent=clicks.toLocaleString('es-MX');$('#stat-ctr').textContent=n?(100*data.totals.clicked/n).toFixed(1)+'%':'—';$('#stat-depth').textContent=n?Math.round(data.totals.avg_depth)+'%':'—';$('#engagement-start').textContent='Misma selección de fechas. Medición disponible desde '+(data.startedAt?dayAt(new Date(data.startedAt)):'esta actualización')+'.'+(!n?' Aún no hay recorridos en este periodo.':'');\n function row(target,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=String(value);tr.append(td)}$(target).append(tr)}\n for(const b of data.buttons)row('#engagement-buttons',[b.label,b.clicks||0,b.journeys||0,b.visitors||0]);\n for(const section of data.sections)row('#engagement-sections',[section.label,section.reached,n?Math.round(section.reached/n*100)+'%':'—',section.last]);\n}\nlet textRevision=0,textDirty=false,textLoaded=false;\nfunction changedTexts(){textDirty=true;$('#save-texts').disabled=false;$('#text-status').textContent='Tienes cambios sin publicar.'}\nconst sectionNames=['HOME','¿CÓMO?','MARNEZ','ARENNEA','UBICACIÓN Y CONTACTO'];\nlet editableFields=[];\nfunction filterTexts(){\n const group=$('#text-section').value, query=$('#text-search').value.trim().toLocaleLowerCase();\n const host=$('#text-fields');host.replaceChildren();\n const blocks=new Map();\n for(const field of editableFields){\n  if(field.group!==group || !(field.label+' '+field.value+' '+field.block).toLocaleLowerCase().includes(query))continue;\n  if(!blocks.has(field.block))blocks.set(field.block,[]);\n  blocks.get(field.block).push(field);\n }\n for(const [name,fields] of blocks){\n  const box=document.createElement('fieldset');box.className='copy-field';\n  const legend=document.createElement('legend');legend.textContent=name;\n  const picker=document.createElement('select');picker.setAttribute('aria-label','Elegir campo de '+name);\n  const editor=document.createElement('textarea');editor.rows=3;editor.maxLength=4000;\n  const reset=document.createElement('button');reset.type='button';reset.className='secondary';reset.textContent='Restaurar este campo';\n  for(const f of fields)picker.add(new Option(f.label+' · '+f.default.trim().slice(0,55),f.id));\n  const selected=()=>fields[picker.selectedIndex];\n  function refresh(){const f=selected();editor.value=f.value;editor.setAttribute('aria-label',f.label)}\n  picker.onchange=refresh;\n  editor.oninput=()=>{selected().value=editor.value;changedTexts()};\n  reset.onclick=()=>{selected().value=selected().default;refresh();changedTexts()};\n  refresh();box.append(legend,picker,editor,reset);host.append(box);\n }\n if(!blocks.size)host.textContent='No hay coincidencias en esta sección.';\n}\nasync function loadTexts(){\n const data=await api('/api/admin/texts');\n textRevision=data.revision;textLoaded=true;textDirty=false;editableFields=data.fields.filter(f=>!f.archived);\n const select=$('#text-section'),previous=select.value;\n select.replaceChildren(...sectionNames.map(n=>new Option(n,n)));select.value=sectionNames.includes(previous)?previous:sectionNames[0];\n $('#save-texts').disabled=true;$('#text-status').textContent='Selecciona una sección y el campo que quieres editar.';filterTexts();\n}\n$('#text-section').onchange=filterTexts;$('#text-search').oninput=filterTexts;\n$('#reload-texts').onclick=()=>{if(textDirty&&!confirm('¿Descartar los cambios que no has publicado?'))return;loadTexts().catch(e=>{$('#text-status').textContent=e.message})};\n$('#save-texts').onclick=async()=>{\n if(!textLoaded)return;const values=Object.fromEntries(editableFields.map(f=>[f.id,f.value]));const controls=[...$('#texts-panel').querySelectorAll('button,textarea,select,input')];controls.forEach(c=>c.disabled=true);$('#text-status').textContent='Publicando textos…';\n try{const result=await api('/api/admin/texts',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:textRevision,values})});textRevision=result.revision;textDirty=false;document.querySelectorAll('.copy-field.dirty').forEach(e=>e.classList.remove('dirty'));$('#text-status').textContent='Textos publicados. Ya se muestran en la landing.'}catch(e){$('#text-status').textContent=e.message}finally{controls.forEach(c=>c.disabled=false);$('#save-texts').disabled=!textDirty}\n};\nwindow.addEventListener('beforeunload',e=>{if(textDirty){e.preventDefault();e.returnValue=''}});\ndocument.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));for(const name of ['texts','images','stats'])$('#'+name+'-panel').hidden=name!==button.dataset.tab});\nload().catch(e=>{if($('#login').hidden)$('#global-status').textContent=e.message});\n</script></html>\n";
