  if(path==='/api/admin/images'&&method==='GET'){const rows=await env.DB.prepare('SELECT name,updated FROM images').all();return json({images:slots.map(s=>({...s,updated:rows.results.find(r=>r.name===s.name)?.updated||null}))})}
